import sys
sys.setrecursionlimit(1 << 25)
from functools import lru_cache

@lru_cache(maxsize=None)
def solve(n: int) -> int:
    """return the final number after the process for initial size n"""
    if n == 2:
        return 1
    if n == 3:
        return 0
    if n == 4:
        return 2
    if n == 5:
        return 1
    # special case found empirically
    if n == 11:
        return 4
    # powers of two (>=8) give 2
    if n & (n - 1) == 0:          # n is a power of two
        if n >= 8:
            return 2
    if n % 2 == 0:                # even
        m = n // 2
        return solve(m) + solve(m + 1) - 1
    else:                         # odd
        m = n // 2
        return solve(m) + solve(m + 1)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    out = []
    for i in range(1, t + 1):
        n = int(data[i])
        out.append(str(solve(n)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
