import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    F = [int(next(it)) for _ in range(3 * n)]
    total = 6 * n

    # colour of each card: True = Federico (F), False = Giada (G)
    isF = [False] * (total + 1)
    for x in F:
        isF[x] = True

    # current deck represented as a list of disjoint intervals (contiguous in original order)
    intervals = [(1, total)]

    # moves will be collected from last turn to first, then reversed
    moves_rev = []

    # helper: find a triple in interval [L,R] with the required colour
    # that satisfies the "residue condition" (positions relative to L are 0,1,2 mod 3)
    def find_triple(L: int, R: int, need_F: bool):
        for x in range(L, R + 1):
            if (x - L) % 3 != 0:
                continue
            if isF[x] != need_F:
                continue
            for y in range(x + 1, R + 1):
                if (y - L) % 3 != 1:
                    continue
                if isF[y] != need_F:
                    continue
                for z in range(y + 1, R + 1):
                    if (z - L) % 3 != 2:
                        continue
                    if isF[z] != need_F:
                        continue
                    return (x, y, z)
        return None

    # process turns from last (2n) down to first (1)
    for turn in range(2 * n, 0, -1):
        need_F = (turn % 2 == 1)          # odd -> Federico, even -> Giada
        found = False
        for idx, (L, R) in enumerate(intervals):
            triple = find_triple(L, R, need_F)
            if triple is None:
                continue
            x, y, z = triple
            moves_rev.append((x, y, z))

            # split the interval into the four gaps
            new_intervals = []
            if L <= x - 1:
                new_intervals.append((L, x - 1))
            if x + 1 <= y - 1:
                new_intervals.append((x + 1, y - 1))
            if y + 1 <= z - 1:
                new_intervals.append((y + 1, z - 1))
            if z + 1 <= R:
                new_intervals.append((z + 1, R))

            # replace the current interval with the (possibly empty) list of new intervals
            intervals = intervals[:idx] + new_intervals + intervals[idx + 1:]
            found = True
            break

        # according to the statement a solution exists, so we should always find a move
        if not found:
            # this should never happen; fallback would be to try other orders,
            # but we rely on the guarantee.
            raise RuntimeError("No valid move found – internal error")

    # reverse to obtain the forward order of turns
    moves = moves_rev[::-1]

    out_lines = []
    for a, b, c in moves:
        out_lines.append(f"{a} {b} {c}")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
